-- Fail closed for financial exports and cash-flow analytics when transaction
-- currency does not match the tenant's canonical company currency.
-- Canonical implementations are applied by this migration in the live DB.

create or replace function public.cash_liquidity_snapshot(p_company_id uuid,p_from date default current_date,p_to date default (current_date+30)) returns table(period_date date,inflows numeric,outflows numeric,net_cash numeric,cumulative_net numeric,risk_level text) language plpgsql stable set search_path='public' as $function$ begin if p_company_id is null or public.current_company_id() is null then raise exception 'TENANT_REQUIRED'; end if; if p_company_id<>public.current_company_id() then raise exception 'TENANT_CONTEXT_MISMATCH'; end if; if p_from>p_to or p_to-p_from>366 then raise exception 'INVALID_CASHFLOW_WINDOW'; end if; if exists(select 1 from public.payments p join public.companies c on c.id=p_company_id where p.company_id=p_company_id and p.payment_date between p_from and p_to and upper(trim(coalesce(p.currency,'')))<>upper(trim(coalesce(c.currency,'')))) then raise exception 'FINANCIAL_CURRENCY_MISMATCH'; end if; return query with days as(select generate_series(p_from,p_to,'1 day')::date d),flow as(select payment_date d,sum(amount) filter(where direction='in') inflow,sum(amount) filter(where direction='out') outflow from payments where company_id=p_company_id and payment_date between p_from and p_to group by payment_date),x as(select days.d,coalesce(inflow,0) inflow,coalesce(outflow,0) outflow from days left join flow on flow.d=days.d),y as(select d,inflow,outflow,inflow-outflow net,sum(inflow-outflow) over(order by d) cumulative from x) select d,inflow,outflow,net,cumulative,case when cumulative<0 then 'critical' when cumulative>0 and cumulative<greatest(outflow,1) then 'high' else 'normal' end from y order by d; end; $function$;

create or replace function public.get_sales_export_rows(p_company_id uuid,p_max_rows integer default 10000) returns jsonb language plpgsql stable set search_path='public' as $function$ declare v_company_id uuid:=public.current_company_id(); v_limit integer; v_result jsonb; begin if v_company_id is null then raise exception 'TENANT_CONTEXT_REQUIRED'; end if; if p_company_id is distinct from v_company_id then raise exception 'TENANT_CONTEXT_MISMATCH'; end if; if p_max_rows is null then v_limit:=10000; elsif p_max_rows<1 or p_max_rows>10000 then raise exception 'EXPORT_ROW_LIMIT_INVALID: p_max_rows must be between 1 and 10000'; else v_limit:=p_max_rows; end if; if exists(select 1 from public.sales_invoices s join public.companies c on c.id=v_company_id where s.company_id=v_company_id and s.status not in ('cancelled','void') and upper(trim(coalesce(s.currency,'')))<>upper(trim(coalesce(c.currency,'')))) then raise exception 'FINANCIAL_CURRENCY_MISMATCH'; end if; if exists(select 1 from public.sales_invoices s where s.company_id=v_company_id and s.status not in ('cancelled','void') offset v_limit limit 1) then raise exception 'EXPORT_TOO_LARGE: sales export exceeds safe row limit'; end if; select coalesce(jsonb_agg(jsonb_build_object('invoice_number',s.invoice_number,'customer',c.name,'invoice_date',s.invoice_date,'total',s.total,'paid_amount',s.paid_amount,'status',s.status) order by s.invoice_date desc),'[]'::jsonb) into v_result from public.sales_invoices s left join public.customers c on c.id=s.customer_id and c.company_id=v_company_id where s.company_id=v_company_id and s.status not in ('cancelled','void'); return jsonb_build_object('rows',v_result,'count',jsonb_array_length(v_result)); end; $function$;

create or replace function public.get_purchase_export_rows(p_company_id uuid,p_max_rows integer default 10000) returns jsonb language plpgsql stable set search_path='public' as $function$ declare v_company_id uuid:=public.current_company_id(); v_limit integer; v_result jsonb; begin if v_company_id is null then raise exception 'TENANT_CONTEXT_REQUIRED'; end if; if p_company_id is distinct from v_company_id then raise exception 'TENANT_CONTEXT_MISMATCH'; end if; if p_max_rows is null then v_limit:=10000; elsif p_max_rows<1 or p_max_rows>10000 then raise exception 'EXPORT_ROW_LIMIT_INVALID: p_max_rows must be between 1 and 10000'; else v_limit:=p_max_rows; end if; if exists(select 1 from public.purchase_invoices p join public.companies c on c.id=v_company_id where p.company_id=v_company_id and p.status not in ('cancelled','void') and upper(trim(coalesce(p.currency,'')))<>upper(trim(coalesce(c.currency,'')))) then raise exception 'FINANCIAL_CURRENCY_MISMATCH'; end if; if exists(select 1 from public.purchase_invoices p where p.company_id=v_company_id and p.status not in ('cancelled','void') offset v_limit limit 1) then raise exception 'EXPORT_TOO_LARGE: purchase export exceeds safe row limit'; end if; select coalesce(jsonb_agg(jsonb_build_object('invoice_number',p.invoice_number,'supplier',s.name,'invoice_date',p.invoice_date,'total',p.total,'paid_amount',p.paid_amount,'status',p.status) order by p.invoice_date desc),'[]'::jsonb) into v_result from public.purchase_invoices p left join public.suppliers s on s.id=p.supplier_id and s.company_id=v_company_id where p.company_id=v_company_id and p.status not in ('cancelled','void'); return jsonb_build_object('rows',v_result,'count',jsonb_array_length(v_result)); end; $function$;

create or replace function public.get_receivables_export_rows(p_company_id uuid,p_max_rows integer default 10000) returns jsonb language plpgsql stable set search_path='public' as $function$ declare v_company_id uuid:=public.current_company_id(); v_limit integer; v_result jsonb; begin if v_company_id is null then raise exception 'TENANT_CONTEXT_REQUIRED'; end if; if p_company_id is distinct from v_company_id then raise exception 'TENANT_CONTEXT_MISMATCH'; end if; if p_max_rows is null then v_limit:=10000; elsif p_max_rows<1 or p_max_rows>10000 then raise exception 'EXPORT_ROW_LIMIT_INVALID: p_max_rows must be between 1 and 10000'; else v_limit:=p_max_rows; end if; if exists(select 1 from public.sales_invoices s join public.companies c on c.id=v_company_id where s.company_id=v_company_id and s.status not in ('cancelled','void') and upper(trim(coalesce(s.currency,'')))<>upper(trim(coalesce(c.currency,'')))) then raise exception 'FINANCIAL_CURRENCY_MISMATCH'; end if; if exists(select 1 from public.sales_invoices s where s.company_id=v_company_id and s.status not in ('cancelled','void') and greatest(s.total-s.paid_amount,0)>0 offset v_limit limit 1) then raise exception 'EXPORT_TOO_LARGE: receivables export exceeds safe row limit'; end if; select coalesce(jsonb_agg(jsonb_build_object('invoice_number',s.invoice_number,'customer',c.name,'invoice_date',s.invoice_date,'due_date',s.due_date,'total',s.total,'paid_amount',s.paid_amount,'balance',case when s.total is null or s.paid_amount is null then null else greatest(s.total-s.paid_amount,0) end) order by s.invoice_date desc),'[]'::jsonb) into v_result from public.sales_invoices s left join public.customers c on c.id=s.customer_id and c.company_id=v_company_id where s.company_id=v_company_id and s.status not in ('cancelled','void') and greatest(s.total-s.paid_amount,0)>0; return jsonb_build_object('rows',v_result,'count',jsonb_array_length(v_result),'as_of',current_date); end; $function$;
